import React from 'react';

interface StatusBadgeProps {
  status: 'ready' | 'loading' | 'error' | 'disabled' | 'neutral';
  label: string;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({ status, label }) => {
  const styles = {
    ready: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
    loading: 'bg-teal-500/10 text-teal-400 border-teal-500/20 animate-pulse',
    error: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
    disabled: 'bg-slate-800/60 text-slate-400 border-slate-700/50',
    neutral: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
  };

  const dots = {
    ready: 'bg-emerald-400',
    loading: 'bg-teal-400',
    error: 'bg-rose-400',
    disabled: 'bg-slate-500',
    neutral: 'bg-blue-400',
  };

  return (
    <span
      className={`inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${styles[status]}`}
    >
      <span className={`w-1.5 h-1.5 rounded-full ${dots[status]}`} />
      <span>{label}</span>
    </span>
  );
};

export default StatusBadge;
